            </div>
            <Link className="botao" to={`/escola/desempenho/${alunoId}`}>
              <Icone nome="grafico" tamanho={20} /> Ver desempenho
            </Link>
          </section>
        )}

        <Passos feitos={feitos} />

        {erro && <p className="erro" role="alert">{erro}</p>}

        {pendentes.length > 0 && (
