import re
p='site/server/src/regras.js'
s=open(p,encoding='utf-8').read()
old=s[s.index('// Jogos do catálogo'):s.index('export function calcularXp')]
new='''// Jogos do catálogo que treinam pelo menos uma habilidade (tag) do PDI.
// Os que cobrem mais tópicos do PDI vêm primeiro.
export function sugerirJogos(itens, jogos) {
  const habilidades = new Set(itens.map((i) => i.habilidade))
  const cobertas = (j) => j.habilidades.filter((h) => habilidades.has(h)).length
  return jogos.filter((j) => cobertas(j) > 0).sort((a, b) => cobertas(b) - cobertas(a))
}

// Nível (1 a 3) que o jogo recebe: o maior nível, entre as tags do PDI que o jogo treina.
export function nivelDoJogo(itens, jogo) {
  const niveis = itens.filter((i) => jogo.habilidades.includes(i.habilidade)).map((i) => Number(i.nivel))
  const nivel = Math.max(1, ...niveis.filter(Number.isFinite))
  return Math.min(3, Math.round(nivel))
}

'''
s=s.replace(old,new)
open(p,'w',encoding='utf-8').write(s)

p='site/server/src/regras.test.js'
s=open(p,encoding='utf-8').read()
s=s.replace("import { sugerirJogos,","import { sugerirJogos, nivelDoJogo,")
s+='''
test('jogos que cobrem mais tópicos do PDI vêm primeiro', () => {
  const itens = [{ habilidade: 'empatia', nivel: 1 }, { habilidade: 'resposta-social', nivel: 1 }, { habilidade: 'reconhecer-emocoes', nivel: 1 }]
  assert.deepEqual(sugerirJogos(itens, jogos).map((j) => j.id), ['sequencia', 'memoria'])
})

test('o nível do jogo vem das tags do PDI que ele treina, entre 1 e 3', () => {
  const seq = jogos[1]
  assert.equal(nivelDoJogo([{ habilidade: 'empatia', nivel: 2 }, { habilidade: 'resposta-social', nivel: 3 }], seq), 3)
  assert.equal(nivelDoJogo([{ habilidade: 'reconhecer-emocoes', nivel: 3 }], seq), 1)
  assert.equal(nivelDoJogo([{ habilidade: 'empatia', nivel: 9 }], seq), 3)
})
'''
open(p,'w',encoding='utf-8').write(s)
