    tray: { x: 0, y: trayY, w, h: trayH, radius: 0 },
    trayTitle: { x: w / 2, y: trayY + 27 },
    options: [{ x: w / 2 - opt / 2 - 12, y: optY }, { x: w / 2 + opt / 2 + 12, y: optY }],
    end: endButtons(w / 2, trayY + 74),
  };

