content.content:
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) {
  --bg: #17131d; --surface: #221d2a; --fg: #ece8f1; --muted: #a99fb5; --line: #3a3345; --accent: #b59af0; --bezel: #050307; color-scheme: dark } }
:root[data-theme="dark"] { --bg: #17131d; --surface: #221d2a; --fg: #ece8f1; --muted: #a99fb5; --line: #3a3345; --accent: #b59af0; --bezel: #050307; color-scheme: dark }

body { background: var(--bg); color: var(--fg); font-family: var(--font-body); font-size: 16px; line-height: 1.5; }
.wrap { max-width: 1280px; margin: 0 auto; padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); padding-block: 32px 64px; display: grid; gap: 28px; }
h1, h2, h3 { font-family: var(--font-display); margin: 0; line-height: 1.15; text-wrap: balance; }
h1 { font-size: clamp(28px, 4.4vw, 42px); font-weight: 800; }
h2 { font-size: 20px; font-weight: 800; }
h3 { font-size: 15px; font-weight: 600; }
p { margin: 0; max-width: 70ch; }
.eyebrow { font-size: 13px; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); font-weight: 700; }
header.intro { display: grid; gap: 10px; }
code { font-size: .92em; }

.layout { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 24px; align-items: start; }
@media (max-width: 980px) { .layout { grid-template-columns: minmax(0, 1fr); } }
.viewer { display: grid; gap: 12px; min-width: 0; }
.devices { display: flex; flex-wrap: wrap; gap: 8px; }
.seg { display: inline-flex; flex-wrap: wrap; border: 1px solid var(--line); border-radius: 10px; overflow: hidden; background: var(--surface); }
.seg button, .tool { font: inherit; font-size: 14px; border: 0; background: none; color: var(--fg); padding: 8px 12px; cursor: pointer; min-height: 40px; }
.seg button[aria-pressed="true"] { background: var(--accent); color: var(--surface); font-weight: 700; }
.seg button:focus-visible, .tool:focus-visible, input:focus-visible { outline: 3px solid var(--accent); outline-offset: 1px; }
.frame-host { display: flex; justify-content: center; }
.device { background: var(--bezel); border-radius: 22px; padding: 14px; max-width: 100%; }
.device.desk { border-radius: 10px; padding: 26px 8px 8px; position: relative; }
.device.desk::before { content: ""; position: absolute; top: 9px; left: 12px; width: 42px; height: 8px; background: radial-gradient(circle at 4px 4px, #e46a5e 3.5px, transparent 4px), radial-gradient(circle at 20px 4px, #e4b85e 3.5px, transparent 4px), radial-gradient(circle at 36px 4px, #6ebf73 3.5px, transparent 4px); }
.screen { position: relative; overflow: hidden; border-radius: 8px; background: #120d1a; }
.desk .screen { border-radius: 2px; }
.stage { position: absolute; left: 0; top: 0; width: 960px; height: 600px; transform-origin: 0 0; }
.dev-note { font-size: 14px; color: var(--muted); font-variant-numeric: tabular-nums; }

.panel { display: grid; gap: 14px; min-width: 0; }
.card { background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 16px; display: grid; gap: 12px; min-width: 0; }
.row { display: grid; gap: 6px; }
.row > label, .row > .lbl { font-size: 14px; font-weight: 700; }
.hint-txt { font-size: 13px; color: var(--muted); }
input[type="text"] { font: inherit; font-size: 15px; padding: 8px 10px; border: 1px solid var(--line); border-radius: 8px; background: var(--bg); color: var(--fg); min-height: 40px; width: 100%; box-sizing: border-box; }
.check { display: flex; gap: 10px; align-items: flex-start; font-size: 15px; cursor: pointer; }
.check input { width: 20px; height: 20px; margin: 2px 0 0; accent-color: var(--accent); flex: none; }
.swatches { display: flex; gap: 8px; }
.swatches button { width: 40px; height: 40px; border-radius: 10px; border: 2px solid var(--line); cursor: pointer; }
.swatches button[aria-pressed="true"] { border-color: var(--fg); box-shadow: 0 0 0 2px var(--surface), 0 0 0 4px var(--accent); }
.tools { display: flex; flex-wrap: wrap; gap: 8px; }
.tool { border: 1px solid var(--line); border-radius: 8px; background: var(--bg); }
.metrics { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.metrics div { border: 1px solid var(--line); border-radius: 10px; padding: 8px 10px; display: grid; }
.metrics b { font-family: var(--font-display); font-size: 26px; font-variant-numeric: tabular-nums; line-height: 1.1; }
.metrics span { font-size: 13px; color: var(--muted); }
#log { margin: 0; padding: 0; list-style: none; display: grid; gap: 6px; font-size: 13px; }
#log li { background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 6px 8px; overflow-x: auto; }
#log code { white-space: pre; }
.states { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 10px 24px; }
.states li { font-size: 15px; }
.states ul { margin: 0; padding-left: 18px; display: grid; gap: 6px; }

/* ===== Jogo (direção B · Papel recortado) — paleta fixa ===== */
.g { --ink: #2a1f3d; --ink-soft: #57466e; --paper: #fffaf2; --grid: #e8d8c4; --tray: #7fc8a9; --sel: #6a3fc8; --card: #ffd9a8;
  position: absolute; inset: 0; width: 960px; height: 600px; overflow: hidden; background: var(--card); color: var(--ink); font-family: "Atkinson Hyperlegible", system-ui, sans-serif; user-select: none; -webkit-user-select: none; -webkit-tap-highlight-color: transparent; }
.g button { font: inherit; color: inherit; -webkit-tap-highlight-color: transparent; touch-action: manipulation; }
.g button:focus-visible { outline: 4px solid var(--sel); outline-offset: 3px; }
.g .bar { position: absolute; left: 0; top: 0; width: 960px; height: 72px; box-sizing: border-box; padding: 0 24px; display: flex; align-items: center; gap: 14px; }
.g .gbtn { height: 56px; min-width: 120px; padding: 0 16px; display: inline-flex; align-items: center; justify-content: center; gap: 8px; font-size: 20px; font-weight: 700; border-radius: 22px; border: 3px solid var(--ink); background: #fff; box-shadow: 3px 3px 0 var(--ink); cursor: pointer; flex: none; }
.g .gbtn:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--ink); }
.g .gbtn svg { width: 22px; height: 22px; flex: none; }
.g .gbtn[aria-pressed="true"] { background: var(--ink); color: #fff; }
.g .gbtn:disabled { opacity: .45; cursor: default; box-shadow: none; }
.g .gbtn.primary { background: var(--sel); color: #fff; }
.g .gbtn.big { height: 64px; font-size: 24px; padding: 0 28px; }
.g #b-ajuda { min-width: 136px; }
.g .instr { flex: 1; min-width: 0; text-align: center; display: grid; gap: 0; }
.g .instr .main { font-family: "Baloo 2", system-ui, sans-serif; font-size: 27px; font-weight: 800; line-height: 1.05; }
.g .instr .sub { font-size: 16px; color: var(--ink-soft); line-height: 1.2; }
.g .left { position: absolute; left: 24px; top: 86px; width: 220px; }
.g .lbl { font-size: 17px; font-weight: 700; margin-bottom: 6px; }
.g .pic { width: 220px; height: 132px; box-sizing: border-box; border: 6px solid #fff; border-radius: 12px; overflow: hidden; rotate: -2deg; box-shadow: 4px 4px 0 var(--ink); background: #fff; }
.g .pic svg { display: block; width: 100%; height: 100%; }
.g .cap { margin-top: 12px; font-size: 15px; line-height: 1.3; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; overflow-wrap: anywhere; }
.g .cap b { font-weight: 700; }
.g .prog { position: absolute; left: 24px; top: 300px; width: 220px; }
.g .prog .lbl { font-variant-numeric: tabular-nums; }
.g .dots { display: grid; grid-template-columns: repeat(5, 18px); gap: 5px; }
.g .dots i { width: 18px; height: 18px; box-sizing: border-box; border-radius: 4px; border: 2px solid var(--ink); background: rgba(255,255,255,.5); }
.g .dots i.on { background: var(--ink); }
.g .boardbg { position: absolute; left: 352px; top: 84px; width: 500px; height: 308px; box-sizing: border-box; background: var(--paper); border: 3px solid var(--ink); border-radius: 22px; box-shadow: 8px 8px 0 var(--ink); }
.g .guide { position: absolute; left: 362px; top: 94px; width: 480px; height: 288px; opacity: 0; pointer-events: none; }
.g.guide-on .guide { opacity: .18; }
.g .cell { position: absolute; width: 96px; height: 96px; border: 0; padding: 0; background: transparent; box-shadow: inset 0 0 0 1px var(--grid); cursor: pointer; }
.g .traybg { position: absolute; left: 24px; top: 404px; width: 912px; height: 184px; box-sizing: border-box; background: var(--tray); border: 3px solid var(--ink); border-radius: 22px; }
.g .slot { position: absolute; width: 72px; height: 72px; box-sizing: border-box; border: 3px dashed rgba(42,31,61,.32); border-radius: 8px; pointer-events: none; }
.g .pc { position: absolute; left: 0; top: 0; width: 96px; height: 96px; border: 0; padding: 0; background: none; transform-origin: 0 0; cursor: pointer; z-index: 2; transition: transform .2s cubic-bezier(.2, .8, .2, 1); }
.g .pc .in { position: absolute; inset: 0; display: block; background: #fff; border-radius: 6px; outline: 5px solid #fff; box-shadow: 4px 4px 0 5px var(--ink); rotate: var(--tilt, 0deg); transition: transform .15s ease-out, rotate .15s ease-out; }
.g .pc .in svg { display: block; width: 100%; height: 100%; border-radius: 6px; }
.g .pc.ok .in { outline: 0; box-shadow: none; border-radius: 0; rotate: 0deg; }
.g .pc.ok .in svg { border-radius: 0; }
.g .pc.ok { cursor: default; z-index: 1; }
.g .pc.sel { z-index: 5; }
.g .pc.sel .in { transform: translateY(-10px) scale(1.08); rotate: 0deg; outline: 7px solid var(--sel); box-shadow: 6px 12px 0 7px rgba(42,31,61,.35); }
.g .pc.moving { z-index: 6; }
.g .pc .badge { position: absolute; right: 6px; bottom: 6px; width: 26px; height: 26px; border-radius: 50%; background: #fff; box-shadow: 0 0 0 2px var(--ink); display: none; place-items: center; }
.g .pc .badge svg { width: 16px; height: 16px; }
.g .pc.ok .badge { display: grid; }
.g.done .pc .badge { display: none; }
.g .pc .tag { position: absolute; left: 50%; top: -48px; transform: translateX(-50%); white-space: nowrap; font-size: 18px; font-weight: 700; background: var(--sel); color: #fff; border-radius: 8px; padding: 2px 10px; display: none; }
.g .pc.sel.intray .tag { display: block; }
.g .pc.glue .in { animation: glue .18s ease-out; }
@keyframes glue { 0% { transform: scale(1.06, .9); } 100% { transform: none; } }
.g .hintbox { position: absolute; width: 96px; height: 96px; pointer-events: none; z-index: 4; display: none; }
.g .hintbox::after { content: ""; position: absolute; inset: 5px; border: 4px dashed var(--sel); border-radius: 10px; }
.g .hintbox span { position: absolute; right: 8px; bottom: 8px; font-size: 14px; font-weight: 700; background: var(--sel); color: #fff; border-radius: 6px; padding: 1px 8px; }
.g .back { position: absolute; width: 72px; height: 72px; box-sizing: border-box; border: 3px dashed var(--sel); border-radius: 8px; background: rgba(255,255,255,.85); color: var(--sel); font-size: 13px; font-weight: 700; line-height: 1.1; padding: 4px; cursor: pointer; z-index: 3; display: none; }
.g .ov { position: absolute; inset: 0; background: var(--card); display: none; flex-direction: column; align-items: center; justify-content: center; gap: 18px; text-align: center; z-index: 10; }
.g .ov h2 { font-family: "Baloo 2", system-ui, sans-serif; font-size: 38px; font-weight: 800; line-height: 1.05; }
.g .ov p { font-size: 19px; max-width: 560px; }
.g .ov .acts { display: flex; gap: 16px; }
.g .ov .bigpic { width: 360px; height: 216px; box-sizing: border-box; border: 8px solid #fff; border-radius: 16px; overflow: hidden; rotate: -2deg; box-shadow: 6px 6px 0 var(--ink); }
.g .ov .bigpic svg { display: block; width: 100%; height: 100%; }
.g .ov .exit { position: absolute; left: 24px; top: 8px; }
.g .ov .cap2 { font-size: 17px; max-width: 420px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; overflow-wrap: anywhere; }
.g .ov .paperstack { width: 120px; height: 84px; position: relative; }
.g .ov .paperstack i { position: absolute; inset: 0; border: 3px solid var(--ink); border-radius: 10px; background: #fff; }
.g .ov .paperstack i:nth-child(1) { rotate: -8deg; background: var(--tray); }
.g .ov .paperstack i:nth-child(2) { rotate: 5deg; background: var(--paper); }
.g .donebox { position: absolute; left: 24px; top: 404px; width: 912px; height: 184px; box-sizing: border-box; background: #fff; border: 3px solid var(--ink); border-radius: 22px; display: none; align-items: center; justify-content: space-between; gap: 20px; padding: 0 32px; z-index: 7; }
.g .donebox h2 { font-family: "Baloo 2", system-ui, sans-serif; font-size: 36px; font-weight: 800; margin: 0; line-height: 1.05; }
.g .donebox p { font-size: 17px; color: var(--ink-soft); }
.g .donebox .acts { display: flex; gap: 14px; }
.g .sticker { position: absolute; left: 770px; top: 62px; z-index: 7; font-family: "Baloo 2", system-ui, sans-serif; font-size: 30px; font-weight: 800; background: #ffd166; border: 3px solid var(--ink); border-radius: 16px; padding: 2px 18px; rotate: 8deg; box-shadow: 4px 4px 0 var(--ink); display: none; }
.g.done .donebox { display: flex; }
.g.done .sticker { display: block; }
.g .scrim { position: absolute; inset: 0; background: rgba(42,31,61,.5); display: none; align-items: center; justify-content: center; z-index: 20; }
.g .dlg { width: 540px; box-sizing: border-box; background: #fff; border: 3px solid var(--ink); border-radius: 22px; box-shadow: 8px 8px 0 var(--ink); padding: 28px 30px; display: grid; gap: 14px; text-align: left; }
.g .dlg h2 { font-family: "Baloo 2", system-ui, sans-serif; font-size: 32px; font-weight: 800; line-height: 1.05; margin: 0; }
.g .dlg p { font-size: 18px; }
.g .dlg .acts { display: flex; gap: 14px; justify-content: flex-end; margin-top: 6px; }
.g .rotate { position: absolute; inset: 0; z-index: 30; background: var(--card); display: none; flex-direction: column; align-items: center; justify-content: center; gap: 22px; }
.g .rotate h2 { font-family: "Baloo 2", system-ui, sans-serif; font-size: 44px; font-weight: 800; margin: 0; }
.g .rotate p { font-size: 22px; }
.g.portrait .rotate { display: flex; }
