// Regras do quebra-cabeça, sem DOM: estado da partida e contagem (docs/quebra-cabeca/REGRAS-E-INTERACOES.md).
// A peça p tem a casa certa p (as duas numeradas de 0 a 14, em ordem de leitura).

export const N = 15
export const COLS = 5

// Bandeja embaralhada de forma repetível: a mesma semente dá a mesma ordem.
export function embaralhar(semente) {
  const a = Array.from({ length: N }, (_, i) => i)
  let x = semente * 9301 + 49297
  for (let i = N - 1; i > 0; i--) {
    x = (x * 9301 + 49297) % 233280
    const j = Math.floor((x / 233280) * (i + 1))
    ;[a[i], a[j]] = [a[j], a[i]]
  }
  return a
}

export class Partida {
  constructor(semente = 1) {
    this.slotOf = {} // peça -> lugar fixo na bandeja
    embaralhar(semente + 3).forEach((p, s) => { this.slotOf[p] = s })
    this.cellOf = Array(N).fill(null) // peça -> casa onde está (ou null, na bandeja)
    this.occ = Array(N).fill(null) // casa -> peça que está nela
    this.sel = null
    this.hint = null
    this.concluida = false
    this.metrics = { attempts: 0, correct: 0, hints: 0 }
    this.msg = ['Escolha uma peça', '']
  }

  certa(p) { return this.cellOf[p] === p }
  certas() { return this.cellOf.filter((c, p) => c === p).length }
  say(principal, apoio = '') { this.msg = [principal, apoio] }
  limpar() { this.sel = null; this.hint = null }

  tocarPeca(p) {
    if (this.concluida) return null
    const noTabuleiro = this.cellOf[p] !== null
    if (noTabuleiro && (this.certa(p) || (this.sel !== null && this.sel !== p))) return this.tocarCasa(this.cellOf[p])
    if (this.sel === p) {
      this.limpar()
      this.say('Escolha uma peça')
    } else {
      this.sel = p
      if (this.hint !== p) this.hint = null
      this.say('Agora toque na casa dela', noTabuleiro ? 'Ou devolva para a bandeja' : '')
    }
    return { tipo: 'selecionou' }
  }

  // Devolve { tipo: 'certa' | 'errada', peca, completa } quando a jogada conta como tentativa.
  tocarCasa(c) {
    if (this.concluida) return null
    const ocupante = this.occ[c]
    if (ocupante !== null && this.certa(ocupante)) { this.say('Essa casa já está completa'); return { tipo: 'nada' } }
    if (this.sel === null) {
      if (ocupante !== null) return this.tocarPeca(ocupante)
      this.say('Primeiro escolha uma peça')
      return { tipo: 'nada' }
    }
    if (ocupante === this.sel) { this.limpar(); this.say('Escolha uma peça'); return { tipo: 'nada' } }
    return this.colocar(this.sel, c)
  }

  colocar(p, c) {
    this.metrics.attempts++
    const de = this.cellOf[p]
    if (de !== null) this.occ[de] = null
    const ocupante = this.occ[c]
    if (ocupante !== null) this.cellOf[ocupante] = null // a peça que estava na casa volta ao lugar dela
    this.cellOf[p] = c
    this.occ[c] = p
    this.limpar()
    if (p === c) {
      this.metrics.correct++
      this.say('Encaixou!')
      return { tipo: 'certa', peca: p, completa: this.certas() === N }
    }
    this.say('Ela fica em outro lugar', 'Pode trocar quando quiser')
    return { tipo: 'errada', peca: p, completa: false }
  }

  devolver() {
    if (this.sel === null || this.cellOf[this.sel] === null) return false
    this.occ[this.cellOf[this.sel]] = null
    this.cellOf[this.sel] = null
    this.limpar()
    this.say('Escolha uma peça')
    return true
  }

  // Cada dica nova soma 1 em hints; repetir a mesma dica não soma.
  ajuda() {
    if (this.concluida) return false
    let alvo = this.sel
    if (alvo === null) {
      alvo = Array.from({ length: N }, (_, i) => i).find((i) => !this.certa(i))
      this.sel = alvo
    }
    if (this.hint === alvo) { this.say('A dica já está na tela', 'É a casa com o contorno tracejado'); return false }
    this.hint = alvo
    this.metrics.hints++
    this.say('A dica mostra a casa dela', this.cellOf[alvo] !== null ? 'Ou devolva para a bandeja' : '')
    return true
  }

  concluir() {
    this.concluida = true
    this.limpar()
    this.say('Pronto!')
  }
}

// Geometria em pixels lógicos de 960 x 600 (REGRAS-E-INTERACOES.md §6). O jogo inteiro é ampliado ou reduzido para caber.
import { COLS, N } from './regras.js'

export const LARGURA = 960
export const ALTURA = 600

export const casaXY = (c) => [362 + (c % COLS) * 96, 94 + Math.floor(c / COLS) * 96]

export function lugarXY(s) {
  const linha = Math.floor(s / 10)
  const coluna = s % 10
  const quantos = linha === 0 ? 10 : N - 10
  const largura = quantos * 72 + (quantos - 1) * 12
  return [24 + (912 - largura) / 2 + coluna * 84, 418 + linha * 84]
}

// Inclinação das peças na bandeja, só para enfeitar.
export const INCLINACOES = [-3, 2, -1.5, 2.5, -2.5, 1, -3, 2, -1, 2.5, -2, 1.5, -3, 2, -1.5]

// Escala FIT: o maior tamanho que cabe sem distorcer, centralizado.
export function encaixar(largura, altura) {
  const escala = Math.min(largura / LARGURA, altura / ALTURA)
  return { escala, x: (largura - LARGURA * escala) / 2, y: (altura - ALTURA * escala) / 2 }
}

// Tablet em retrato: o jogo pede para girar e não conta nada.
export const emRetrato = (largura, altura) => altura > largura

// Monta a imagem no formato 5:3 do tabuleiro: inteira (contain); a sobra recebe a própria imagem
// ampliada e desfocada, para as peças de borda não ficarem iguais (REGRAS-E-INTERACOES.md §5).
import { COLS } from './regras.js'

export const PROPORCAO_TABULEIRO = 5 / 3

export function medidas(proporcao) {
  const larga = proporcao > PROPORCAO_TABULEIRO
  return {
    inteira: { w: larga ? 500 : 300 * proporcao, h: larga ? 500 / proporcao : 300 },
    fundo: { w: larga ? 300 * proporcao : 500, h: larga ? 300 : 500 / proporcao },
  }
}

// Conteúdo de um <symbol viewBox="0 0 500 300">. `filtro` é o id do <filter> de desfoque.
export function simbolo({ url, proporcao, filtro }) {
  const img = (x, y, w, h) => `<image href="${url}" x="${x}" y="${y}" width="${w}" height="${h}" preserveAspectRatio="none"/>`
  if (Math.abs(proporcao - PROPORCAO_TABULEIRO) < 0.01) return img(0, 0, 500, 300)
  const { inteira, fundo } = medidas(proporcao)
  return `<g filter="url(#${filtro})">${img((500 - fundo.w) / 2, (300 - fundo.h) / 2, fundo.w, fundo.h)}</g>`
    + '<rect width="500" height="300" fill="#fff" opacity=".22"/>'
    + img((500 - inteira.w) / 2, (300 - inteira.h) / 2, inteira.w, inteira.h)
}

// Recorte da peça p dentro do símbolo.
export function recorte(p, simboloId) {
  const x = (p % COLS) * 100
  const y = Math.floor(p / COLS) * 100
  return `<svg viewBox="${x} ${y} 100 100" aria-hidden="true"><use href="#${simboloId}" width="500" height="300"/></svg>`
}

