    imgTeste.onload = () => { if (morto) return; fase = 'start'; desenhar() }
    imgTeste.onerror = () => { if (morto) return; fase = 'error'; desenhar() }
    imgTeste.src = imagem.url
  }
  function novaPartida() {
    timers.forEach(clearTimeout)
